from typing import Optional

def parse_money(s: str) -> float | None:
    if not s or s.lower() == 'n/a':
        return None

    # Remove leading/trailing whitespace and dollar sign
    cleaned = s.strip().lstrip('$')

    try:
        # Replace commas with nothing to remove thousands separators
        number_str = cleaned.replace(',', '')

        if not number_str or '.' in number_str:
            float_val = float(number_str)
            return float_val

        # If there's no decimal point, it might still be valid as an integer-like string
        if number_str and all(c.isdigit() for c in number_str):
            return float(number_str)

        raise ValueError("Invalid format")
    except (ValueError, AttributeError):
        return None
